/*
 * A052041  Squares lacking the digit zero in their decimal expansion.
 * https://oeis.org/A052041
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n‑th square that contains no digit 0 in its decimal
 *            expansion. The sequence is generated by testing each integer i,
 *            squaring it, and counting only those squares that pass the
 *            zero‑digit test
 * Range:     u8 n <= 14, u16 n <= 168, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   has_zero_digit
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/has_zero_digit.h"

seq_t a(idx_t n)
{
    /* n is at least 1; we count squares starting with i = 1. */
    idx_t count = 0;
    idx_t i     = 1;

    for (;;) {
        const seq_t square = (seq_t)i * (seq_t)i;
        if (!has_zero_digit(square)) {
            ++count;
            if (count == n)
                return square;
        }
        ++i;
    }
}
